def link_existing_envio_issues(apps, schema_editor):
    """Los faltantes de envio ya creados guardaban el envio solo en el texto
    ("... (envio #39)."): se enlazan al envio para resolverlos como traslado."""
    Inconveniente = apps.get_model("importaciones", "ImportacionInconveniente")
    Envio = apps.get_model("importaciones", "ImportacionEnvio")
    pattern = re.compile(r"envio #(\d+)", re.IGNORECASE)
    for issue in Inconveniente.objects.filter(envio__isnull=True, motivo__icontains="envio #"):
        match = pattern.search(issue.motivo or "")
        if not match:
            continue
        envio_id = int(match.group(1))
        if Envio.objects.filter(pk=envio_id, importacion_id=issue.importacion_id).exists():
            issue.envio_id = envio_id
            issue.save(update_fields=["envio"])


